 function modality623(){const input=document.getElementById('music622_type');if(!input)return;const wrap=document.getElementById('music622_new_wrap');wrap.hidden=input.value!=='__add622';wrap.querySelector('input').required=!wrap.hidden;const type=input.value==='__add622'?wrap.querySelector('input').value.trim():input.value;const samples={'Solista':'Solista - Marisol Sánchez','Dúo':'Dúo Emanuel','Trío':'Trío Luz y Vida','Cuarteto':'Cuarteto Nueva Esperanza','Coro':'Coro Voces de Sion','Conjunto Instrumental':'Conjunto Instrumental Armonía'};const example=samples[type]||(type?type+' Armonía':'Nombre completo del ministerio');document.getElementById('music623_name').placeholder=example;document.getElementById('music623_example').textContent='Ejemplo: '+example+'. Escribe el nombre tal como aparecerá en el certificado.';}
 function age623(){const out=document.getElementById('music623_age'),value=document.getElementById('music623_start')?.value;if(!out)return;const start=new Date(value+'T00:00:00'),now=new Date();if(!value||Number.isNaN(start.getTime())){out.textContent='Selecciona la fecha para ver la trayectoria actual.';return}if(start>now){out.textContent='La fecha no puede ser futura.';return}let months=(now.getFullYear()-start.getFullYear())*12+now.getMonth()-start.getMonth()-(now.getDate()<start.getDate()?1:0);months=Math.max(0,months);const years=Math.floor(months/12),m=months%12,parts=[];if(years)parts.push(years+' '+(years===1?'año':'años'));if(m)parts.push(m+' '+(m===1?'mes':'meses'));out.textContent='Trayectoria actual: '+(parts.join(' y ')||'Menos de un mes');}
